#if CANVAS_PREVIEW_BACKGROUND
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using MoriDesk;

// Only generated fixtures are read. No editor, native window, real library,
// screenshot, clipboard, desktop input or network request is involved.
internal static class CanvasPreviewBackgroundTests {
 static int checks;static string sandbox;
 static void Check(bool value,string message){
  foreach(Window window in Application.Current.Windows)if(window.IsVisible||new WindowInteropHelper(window).Handle!=IntPtr.Zero)throw new InvalidOperationException("A native or visible window was created.");
  if(!value)throw new InvalidOperationException(message);checks++;Console.WriteLine("PASS "+message);
 }
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=MatureCanvasStore.MaximumSceneBytes*2,RecursionLimit=48};}
 static Dictionary<string,object> Map(params object[] values){var map=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)map.Add((string)values[i],values[i+1]);return map;}
 static Dictionary<string,object> Obj(object value){return (Dictionary<string,object>)value;}
 static Dictionary<string,object> Records(Dictionary<string,object> scene){return Obj(Obj(scene["document"])["store"]);}
 static Dictionary<string,object> Shape(string id,string type,Dictionary<string,object> props,string parent="page:page",double x=0,double y=0){return Map("id",id,"typeName","shape","type",type,"props",props,"parentId",parent,"x",x,"y",y,"rotation",0,"index","a1","isLocked",false,"opacity",1,"meta",Map());}
 static byte[] Png(Color left,Color right){const int w=120,h=80;var pixels=new byte[w*h*4];for(int y=0;y<h;y++)for(int x=0;x<w;x++){var color=x<w/2?left:right;int i=(y*w+x)*4;pixels[i]=color.B;pixels[i+1]=color.G;pixels[i+2]=color.R;pixels[i+3]=255;}var bitmap=BitmapSource.Create(w,h,96,96,PixelFormats.Bgra32,null,pixels,w*4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=new MemoryStream()){encoder.Save(stream);return stream.ToArray();}}
 static byte[] Pixels(BitmapSource bitmap){var converted=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);var pixels=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(pixels,converted.PixelWidth*4,0);return pixels;}
 static int ColorCount(BitmapSource bitmap,Func<byte,byte,byte,bool> match){var pixels=Pixels(bitmap);int count=0;for(int i=0;i<pixels.Length;i+=4)if(match(pixels[i+2],pixels[i+1],pixels[i]))count++;return count;}
 static bool Red(byte r,byte g,byte b){return r>160&&r>g+70&&r>b+40;}
 static bool Blue(byte r,byte g,byte b){return b>150&&b>r+60;}
 static string Fingerprint(string path){using(var sha=SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(path)))+":"+File.GetLastWriteTimeUtc(path).Ticks;}
 static CanvasProjectRow Row(MatureCanvasDocument document){return new CanvasProjectRow{Id=document.Id,Name=document.Name,Updated=document.Updated};}
 static BitmapSource Read(FreeCanvasStore legacy,MatureCanvasStore mature,MatureCanvasDocument document){CanvasProjectThumbnail.Invalidate(mature.Root,document.Id);return CanvasProjectThumbnail.Read(legacy,mature,Row(document));}
 static void Save(MatureCanvasStore store,MatureCanvasDocument document,Dictionary<string,object> scene){document.SceneJson=Json().Serialize(scene);store.Save(document);}
 static void Run(){
  string profile=Path.Combine(sandbox,"fixture-profile");var legacy=new FreeCanvasStore(profile);var mature=new MatureCanvasStore(profile);var old=legacy.Create("只有已保存记录，没有导出预览");
  string original=Path.Combine(sandbox,"synthetic-original.png");File.WriteAllBytes(original,Png(Colors.Crimson,Colors.Crimson));var image=legacy.Import(old.Id,original,CancellationToken.None);image.X=40;image.Y=60;old.Items.Add(image);old.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="line",X=180,Y=20,EndX=290,EndY=150,Stroke=5,Color="#0000FF"});old.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",X=10,Y=0,Width=170,Height=35,FontSize=24,Color="#000000",Text="Saved project A"});legacy.Save(old);var document=mature.CreateFromLegacy(old);
  string folder=Path.Combine(mature.Root,document.Id),manifest=Path.Combine(folder,MatureCanvasStore.ManifestName),meta=Path.Combine(folder,CanvasProjectThumbnail.MetadataName),preview=Path.Combine(folder,CanvasProjectThumbnail.ImageName);var protectedPaths=new[]{original,legacy.ImagePath(old.Id,image.Image),Path.Combine(folder,"project.json"),manifest};var before=protectedPaths.ToDictionary(p=>p,Fingerprint);var files=Directory.GetFiles(folder,"*",SearchOption.AllDirectories).OrderBy(p=>p,StringComparer.Ordinal).ToArray();
  var fallback=Read(legacy,mature,document);Check(fallback!=null&&fallback.PixelWidth==320&&fallback.PixelHeight==200&&fallback.IsFrozen,"a saved mature canvas gets a frozen thumbnail before the editor is ever opened");
  Check(ColorCount(fallback,Red)>1000&&ColorCount(fallback,Blue)>50&&ColorCount(fallback,(r,g,b)=>r<50&&g<50&&b<50)>20,"fallback depicts the saved red image, blue line and dark text");
  Check(protectedPaths.All(p=>Fingerprint(p)==before[p])&&files.SequenceEqual(Directory.GetFiles(folder,"*",SearchOption.AllDirectories).OrderBy(p=>p,StringComparer.Ordinal)),"fallback changes no source/project bytes, timestamps or directory contents and creates no sidecar");
  Check(ReferenceEquals(fallback,CanvasProjectThumbnail.Read(legacy,mature,Row(document))),"unchanged mature fallback is reused from the decoded thumbnail cache");
  using(var stream=File.Open(protectedPaths[1],FileMode.Open,FileAccess.ReadWrite,FileShare.None))Check(stream.Length>0,"fallback leaves no project image file locked");
  CanvasProjectThumbnail.Invalidate(mature.Root,document.Id);var reopened=CanvasProjectThumbnail.Read(new FreeCanvasStore(profile),new MatureCanvasStore(profile),Row(document));Check(Pixels(reopened).SequenceEqual(Pixels(fallback)),"fresh stores recover the same overview from saved scene data without an editor");
  CanvasProjectThumbnail.SaveMature(mature,document,"data:image/png;base64,"+Convert.ToBase64String(Png(Colors.Blue,Colors.Blue)));var exact=Read(legacy,mature,document);Check(ColorCount(exact,Blue)>9000&&ColorCount(exact,Red)==0,"a valid exact engine export takes precedence over the native overview");
  File.WriteAllText(meta,"{ broken metadata");Check(ColorCount(Read(legacy,mature,document),Red)>1000,"malformed optional preview metadata falls back to the intact saved scene");
  CanvasProjectThumbnail.SaveMature(mature,document,"data:image/png;base64,"+Convert.ToBase64String(Png(Colors.Blue,Colors.Blue)));File.WriteAllBytes(preview,new byte[]{1,2,3});Check(ColorCount(Read(legacy,mature,document),Red)>1000,"a torn preview PNG/metadata pair falls back instead of blocking the card");
  var damagedMetadata=Obj(Json().DeserializeObject(File.ReadAllText(meta)));using(var sha=SHA256.Create())damagedMetadata["ImageHash"]=BitConverter.ToString(sha.ComputeHash(new byte[]{1,2,3})).Replace("-","");File.WriteAllText(meta,Json().Serialize(damagedMetadata));Check(ColorCount(Read(legacy,mature,document),Red)>1000,"even a hash-matching invalid PNG is rejected and falls back to the saved scene");
  var scene=Obj(Json().DeserializeObject(document.SceneJson));var records=Records(scene);Obj(records["shape:"+image.Id])["x"]=300;Save(mature,document,scene);Check(ColorCount(Read(legacy,mature,document),Red)>1000,"changed saved geometry invalidates an old export and is still previewable");
  var empty=mature.Create("真的空白");Check(Read(legacy,mature,empty)==null,"a genuinely empty canvas stays empty");
  records["page:second"]=Map("id","page:second","typeName","page","name","第二页","index","a2","meta",Map());var session=Obj(scene["session"]);session["currentPageId"]="page:second";session["pageStates"]=((object[])session["pageStates"]).Concat(new object[]{Map("pageId","page:second","camera",Map("x",0,"y",0,"z",1),"selectedShapeIds",new object[0],"focusedGroupId",null)}).ToArray();Save(mature,document,scene);Check(Read(legacy,mature,document)==null,"a blank current page does not accidentally preview another page's content");
  records["shape:second"]=Shape("shape:second","geo",Map("w",120,"h",70,"fill","solid","color","green"),"page:second");Save(mature,document,scene);var second=Read(legacy,mature,document);Check(ColorCount(second,(r,g,b)=>g>100&&g>r+50)>4000&&ColorCount(second,Red)==0,"only current-page shapes contribute to the overview");
  var grouped=mature.Create("组与旋转");var groupScene=Obj(Json().DeserializeObject(grouped.SceneJson));var groupRecords=Records(groupScene);groupRecords["shape:group"]=Shape("shape:group","group",Map(),"page:page",200,100);Obj(groupRecords["shape:group"])["rotation"]=Math.PI/2;groupRecords["shape:child"]=Shape("shape:child","geo",Map("w",100,"h",40,"color","red","fill","solid"),"shape:group");groupRecords["shape:invisible"]=Shape("shape:invisible","geo",Map("w",100,"h",100,"color","blue","fill","solid"),"page:page",1000,1000);Obj(groupRecords["shape:invisible"])["opacity"]=0;Save(mature,grouped,groupScene);var rotated=Read(legacy,mature,grouped);var rp=Pixels(rotated);int minX=320,maxX=0,minY=200,maxY=0;for(int y=0;y<200;y++)for(int x=0;x<320;x++){int i=(y*320+x)*4;if(Red(rp[i+2],rp[i+1],rp[i])){minX=Math.Min(minX,x);maxX=Math.Max(maxX,x);minY=Math.Min(minY,y);maxY=Math.Max(maxY,y);}}Check(maxY-minY>2*(maxX-minX)&&ColorCount(rotated,Blue)==0,"group transforms rotate children correctly while fully transparent distant shapes do not distort fitting");
  var pictureLegacy=legacy.Create("裁剪和翻转");string source=Path.Combine(sandbox,"synthetic-split.png");File.WriteAllBytes(source,Png(Colors.Red,Colors.Blue));pictureLegacy.Items.Add(legacy.Import(pictureLegacy.Id,source,CancellationToken.None));legacy.Save(pictureLegacy);var pictures=mature.CreateFromLegacy(pictureLegacy);var pictureScene=Obj(Json().DeserializeObject(pictures.SceneJson));var pictureRecords=Records(pictureScene);var pictureRecord=pictureRecords.Values.Select(Obj).Single(r=>(string)r["typeName"]=="shape"&&(string)r["type"]=="image");var pictureProps=Obj(pictureRecord["props"]);pictureProps["crop"]=Map("topLeft",Map("x",0,"y",0),"bottomRight",Map("x",.5,"y",1));Save(mature,pictures,pictureScene);var cropped=Read(legacy,mature,pictures);Check(ColorCount(cropped,Red)>1000&&ColorCount(cropped,Blue)==0,"cropped images preview the saved visible portion rather than the full source");
  pictureProps["crop"]=null;pictureProps["flipX"]=true;Save(mature,pictures,pictureScene);var flipped=Read(legacy,mature,pictures);var fp=Pixels(flipped);int left=(100*320+110)*4,right=(100*320+210)*4;Check(Blue(fp[left+2],fp[left+1],fp[left])&&Red(fp[right+2],fp[right+1],fp[right]),"saved horizontal image flips are reflected in the overview");
  string resourcePath=mature.ResourcePath(pictures,pictures.Resources.Single());File.WriteAllBytes(resourcePath,new byte[]{1,2,3,4});var broken=Read(legacy,mature,pictures);Check(broken!=null&&ColorCount(broken,(r,g,b)=>r>150&&r<240&&r==g&&g==b)>1000,"undecodable registered image bytes get a bounded placeholder instead of a blank card");
  File.Move(resourcePath,resourcePath+".missing-fixture");try{bool rejected=false;try{Read(legacy,mature,pictures);}catch(IOException){rejected=true;}var invalidRow=CanvasProjectsPage.QueryProjects(legacy,mature).Single(r=>r.Id==pictures.Id);Check(rejected&&!string.IsNullOrEmpty(invalidRow.Error)&&CanvasProjectThumbnail.Read(legacy,mature,invalidRow)==null,"a missing registered file degrades to a safe unreadable-project card instead of dereferencing another path");}finally{File.Move(resourcePath+".missing-fixture",resourcePath);}
  var budgetLegacy=legacy.Create("解码预算");budgetLegacy.Items.Add(legacy.Import(budgetLegacy.Id,original,CancellationToken.None));legacy.Save(budgetLegacy);var budgetDoc=mature.CreateFromLegacy(budgetLegacy);var budgetScene=Obj(Json().DeserializeObject(budgetDoc.SceneJson));var budgetRecords=Records(budgetScene);var template=budgetRecords.Values.Select(Obj).Single(r=>(string)r["typeName"]=="shape");for(int i=0;i<160;i++){string id="shape:overlap"+i;var duplicate=Obj(Json().DeserializeObject(Json().Serialize(template)));duplicate["id"]=id;budgetRecords[id]=duplicate;}Save(mature,budgetDoc,budgetScene);var bounded=Read(legacy,mature,budgetDoc);Check(bounded!=null&&ColorCount(bounded,(r,g,b)=>r>150&&r<240&&r==g&&g==b)>1000,"overlapping images exhaust the 4 MiB per-preview decode budget and later images use bounded placeholders");
  var cancelled=CanvasProjectThumbnail.ReadAsync(legacy,mature,new CanvasProjectRow{Id=new string('f',32)},()=>false).GetAwaiter().GetResult();Check(cancelled==null,"an off-screen cancelled request avoids reading even a nonexistent project");
  var asyncImage=Task.Run(async()=>await CanvasProjectThumbnail.ReadAsync(legacy,mature,Row(grouped),()=>true)).GetAwaiter().GetResult();Check(asyncImage!=null&&asyncImage.IsFrozen,"asynchronous fallback runs on its own STA and returns a detached frozen bitmap");
  for(int i=0;i<36;i++){var board=mature.Create("缓存 "+i);var copy=Obj(Json().DeserializeObject(grouped.SceneJson));Save(mature,board,copy);CanvasProjectThumbnail.Read(legacy,mature,Row(board));}Check(CanvasProjectThumbnail.CacheBytesForTests<=CanvasProjectThumbnail.CacheBudget,"scrolling many saved mature projects stays within the existing 8 MiB decoded cache budget");
  Check(!File.Exists(Path.Combine(folder,"thumbnail-native.png"))&&Fingerprint(original)==before[original],"all fallback scenarios retain the original synthetic source without hidden export writes");
 }
 [STAThread]static int Main(string[] args){try{
  if(args.Length!=1||!Path.IsPathRooted(args[0]))throw new ArgumentException("A prepared absolute sandbox is required.");sandbox=Path.GetFullPath(args[0]);if(!File.Exists(Path.Combine(sandbox,".canvas-preview-background-sandbox")))throw new InvalidOperationException("Refusing to run outside the prepared sandbox.");Environment.SetEnvironmentVariable("MORI_DESK_DATA",Path.Combine(sandbox,"data"));var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Mori.Theme.Set("dark");
  CanvasProjectGalleryTests.Run(Path.Combine(sandbox,"existing-gallery-regression"),Check);Run();string summary="PASS "+checks+" checks\r\nSandbox: "+sandbox;File.WriteAllText(Path.Combine(sandbox,"canvas-preview-tests.txt"),summary);Console.WriteLine(summary);return 0;
 }catch(Exception error){Console.Error.WriteLine(error);if(sandbox!=null)File.WriteAllText(Path.Combine(sandbox,"canvas-preview-tests.txt"),"FAIL after "+checks+" checks\r\n"+error);return 1;}}
}
#endif
